) AS v(rc_id, full_name, status_before, result, result_source);

-- ---------------------------------------------------------------------------
-- PRE-FLIGHT
-- ---------------------------------------------------------------------------
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM ca0243_result;
  IF n <> 281 THEN RAISE EXCEPTION 'PRE: % result rows listed, expected 281', n; END IF;

  SELECT count(*) INTO n
    FROM ca0243_result c
    JOIN essentials.race_candidates rc ON rc.id = c.rc_id AND rc.full_name = c.full_name
                                      AND rc.candidate_status = c.status_before
    JOIN essentials.races ra ON ra.id = rc.race_id AND ra.position_name NOT LIKE 'U.S. Representative%'
    JOIN essentials.elections e ON e.id = ra.election_id AND e.election_type = 'primary'
                               AND e.state = 'WI' AND e.election_date = '2026-08-11';
  IF n <> 281 THEN RAISE EXCEPTION 'PRE: only % of 281 rows match id / name / status / race', n; END IF;

  SELECT count(*) INTO n FROM ca0243_result c JOIN essentials.race_candidates rc ON rc.id = c.rc_id
   WHERE NOT (rc.result IS NULL OR (rc.result = c.result AND rc.result_source = c.result_source));
  IF n <> 0 THEN RAISE EXCEPTION 'PRE: % rows already carry a different result', n; END IF;

  -- Nothing unreviewed: every stale non-House Wisconsin primary row is here.
  SELECT count(*) INTO n
    FROM essentials.race_candidates rc
    JOIN essentials.races ra ON ra.id = rc.race_id AND ra.position_name NOT LIKE 'U.S. Representative%'
    JOIN essentials.elections e ON e.id = ra.election_id AND e.election_type = 'primary'
                               AND e.state = 'WI' AND e.election_date = '2026-08-11'
   WHERE rc.result IS NULL AND rc.candidate_status <> 'withdrawn'
     AND rc.id NOT IN (SELECT rc_id FROM ca0243_result);
  IF n <> 0 THEN RAISE EXCEPTION 'PRE: % stale Wisconsin primary rows were not reviewed', n; END IF;

  RAISE NOTICE 'CA_0243 pre-flight OK';
END $$;

-- ---------------------------------------------------------------------------
-- Record the results. Guarded on result IS NULL.
-- ---------------------------------------------------------------------------
UPDATE essentials.race_candidates rc
   SET result             = c.result,
       result_source      = c.result_source,
       result_recorded_at = '2026-09-24T00:00:00Z'
  FROM ca0243_result c
 WHERE rc.id = c.rc_id
   AND rc.result IS NULL;

-- ---------------------------------------------------------------------------
-- VERIFY
-- ---------------------------------------------------------------------------
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM ca0243_result c JOIN essentials.race_candidates rc ON rc.id = c.rc_id
   WHERE rc.result = c.result AND rc.result_source = c.result_source AND rc.result_recorded_at IS NOT NULL
     AND rc.candidate_status = c.status_before;
  IF n <> 281 THEN RAISE EXCEPTION 'POST: % of 281 rows carry their result with candidate_status unchanged', n; END IF;

  SELECT count(*) INTO n FROM ca0243_result WHERE result = 'won';
  IF n <> 234 THEN RAISE EXCEPTION 'POST: % won, expected 234', n; END IF;

  -- Exactly one winner in every party primary race this file touches.
  SELECT count(*) INTO n
    FROM (SELECT ra.id FROM ca0243_result c JOIN essentials.race_candidates rc ON rc.id = c.rc_id
            JOIN essentials.races ra ON ra.id = rc.race_id
           GROUP BY ra.id, coalesce(ra.primary_party, '')
          HAVING count(*) FILTER (WHERE c.result = 'won') <> 1) x;
  IF n <> 0 THEN RAISE EXCEPTION 'POST: % Wisconsin primary races do not have exactly one winner', n; END IF;

  RAISE NOTICE 'CA_0243 applied: 281 Wisconsin primary results (234 won, 47 lost)';
END $$;

COMMIT;
